lib = '''"""Reusable ARC-style grid helpers."""


def background(grid):
    """Return the most frequent color in the grid (the background)."""
    from collections import Counter
    return Counter(c for row in grid for c in row).most_common(1)[0][0]


def diagonal_lines(grid, min_len=2):
    """Group non-background cells into maximal same-color diagonal lines.

    Returns a list of (color, cells, (dr, dc)) where cells are ordered along
    the line and (dr, dc) is the unit step from first to last cell.
    Lines shorter than min_len are skipped.
    """
    bg = background(grid)
    h, w = len(grid), len(grid[0])
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg]
    by_color = {}
    for r, c in cells:
        by_color.setdefault(grid[r][c], set()).add((r, c))
    lines = []
    for color, pts in by_color.items():
        seen = set()
        for start in pts:
            if start in seen:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                prev = (start[0] - dr, start[1] - dc)
                if prev in pts:
                    continue  # not the line start in this direction
                line, cur = [], start
                while cur in pts:
                    line.append(cur)
                    seen.add(cur)
                    cur = (cur[0] + dr, cur[1] + dc)
                if len(line) >= min_len:
                    lines.append((color, line, (dr, dc)))
    return lines


def extend_diagonal_lines(grid):
    """Extend each maximal same-color diagonal line (len >= 2) from its open ends.

    An end is open only if the next cell along the line is background AND the end
    cell has no non-background 8-neighbor other than cells of its own line; the
    line then grows along that direction through background cells.
    """
    bg = background(grid)
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    lines = diagonal_lines(out)
    for color, cells, (dr, dc) in lines:
        cellset = set(cells)
        for end, step in ((cells[0], (-dr, -dc)), (cells[-1], (dr, dc))):
            nxt = (end[0] + step[0], end[1] + step[1])
            if not (0 <= nxt[0] < h and 0 <= nxt[1] < w) or out[nxt[0]][nxt[1]] != bg:
                continue
            blocked = any(
                out[nr][nc] != bg and (nr, nc) not in cellset
                for nr in range(end[0] - 1, end[0] + 2)
                for nc in range(end[1] - 1, end[1] + 2)
                if (nr, nc) != end and 0 <= nr < h and 0 <= nc < w
            )
            if blocked:
                continue
            cur = nxt
            while 0 <= cur[0] < h and 0 <= cur[1] < w and out[cur[0]][cur[1]] == bg:
                out[cur[0]][cur[1]] = color
                cur = (cur[0] + step[0], cur[1] + step[1])
    return out
